    {/if}
    {capture $c_3}
      {capture $c_1}
        {=og_text(og_get($v_stat, ['value']))}
      {/capture}
      {=og_include('compose/Text.latte', ['size' => '5xl', 'weight' => 'medium', 'class' => og_s(og_cnv(['flex items-center', og_preset('blocks/presets/defaults.json', ['stats', 'figure'])])), 'children' => (string) $c_1])|noescape}
      {capture $c_2}
        {=og_text(og_get($v_stat, ['label']))}
      {/capture}
      {=og_include('compose/Text.latte', ['size' => 'sm', 'weight' => 'semibold', 'class' => 'leading-5 text-muted-foreground', 'children' => (string) $c_2])|noescape}
    {/capture}
    {=og_include('compose/Stack.latte', ['gap' => '2', 'align' => og_s((og_t(og_eq($v_align, 'center')) ? 'center' : 'start')), 'children' => (string) $c_3])|noescape}
  {/capture}
  {=og_include('compose/Stack.latte', ['gap' => '6', 'align' => og_s((og_t(og_eq($v_align, 'center')) ? 'center' : 'start')), 'class' => og_s(og_cnv([(og_t(og_eq($v_align, 'center')) ? 'text-center' : ''), og_preset('blocks/presets/defaults.json', ['stats', 'column'])])), 'attrs' => og_attrs(['data-testid', 'item']), 'children' => (string) $c_4])|noescape}
{/if}
